list_currencies.code:
var response = await client.Currencies.ListCurrenciesAsync(
    new Dictionary<string, object?> { ["search"] = "dollar", ["active"] = true });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var currency in ((IReadOnlyList<object?>)body["currencies"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{currency["id"]} {currency["code"]} {currency["name"]} {currency["conversion_rate"]} {currency["base"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

