create_currency.code:
var response = await client.Currencies.CreateCurrencyAsync(new Dictionary<string, object?>
{
    ["name"] = "Example Dollar", ["code"] = "XEX", ["symbol"] = "$", ["country"] = "NZ",
    ["conversion_rate"] = 1.2345, ["precision"] = 2, ["rounding"] = "nearest", ["active"] = true,
}, transactionNo: "TXN-IMPORT-0001");
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var currency = (IReadOnlyDictionary<string, object?>)body["currency"]!;
Console.WriteLine($"{currency["id"]} {currency["code"]} {currency["base"]}");

get_currency.code:
var response = await client.Currencies.GetCurrencyAsync(1234,
    new Dictionary<string, object?> { ["field_metadata"] = true });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var currency = (IReadOnlyDictionary<string, object?>)body["currency"]!;
